    'attribute vec4 a_Position;\n attribute vec2 a_Texcoord;\n attribute vec3 a_Normal;\n uniform mat4 u_MvpMatrix;\n uniform mat4 u_WorldMat;\n varying vec2 v_Texcoord;\nvarying vec3 v_Normal;\nuniform float u_OutlineBounds;\n\n#ifdef BONE\n    attribute vec4 a_BoneIndices;\n    attribute vec4 a_BoneWeights;\n    const int c_MaxBoneCount = 24;\n    uniform mat4 u_Bones[c_MaxBoneCount];\n#endif\n#if defined(DIRECTIONLIGHT)\n    varying vec3 v_PositionWorld;\n#endif\n\nvoid main(){\n    v_Texcoord=a_Texcoord;\n    #ifdef BONE\n        mat4 skinTransform=mat4(0.0);\n        skinTransform += u_Bones[int(a_BoneIndices.x)] * a_BoneWeights.x;\n        skinTransform += u_Bones[int(a_BoneIndices.y)] * a_BoneWeights.y;\n        skinTransform += u_Bones[int(a_BoneIndices.z)] * a_BoneWeights.z;\n        skinTransform += u_Bones[int(a_BoneIndices.w)] * a_BoneWeights.w;\n        vec4 position = skinTransform * (a_Position + vec4(normalize(a_Normal)* u_OutlineBounds, 0));\n        gl_Position=u_MvpMatrix * position;\n        mat3 worldMat=mat3(u_WorldMat * skinTransform);\n    #else\n        vec4 position = a_Position +  vec4(normalize(a_Normal)* u_OutlineBounds, 0);\n        gl_Position=u_MvpMatrix * position; \n        mat3 worldMat=mat3(u_WorldMat);\n    #endif\n    v_Normal=worldMat*a_Normal;\n    #if defined(DIRECTIONLIGHT)\n        v_PositionWorld=(u_WorldMat*position).xyz;\n    #endif\n}', 
